/** 读取应用版本号：优先 electronAPI，读不到用兜底值 */
function readVersion() {
  try {
    const api = (typeof window !== 'undefined') ? window.electronAPI : null;
    if (api) {
      const v = api.appVersion || api.version || (api.getAppInfo && api.getAppInfo().version);
      if (v) return String(v);
    }
  } catch (_) {}
  return FALLBACK_VERSION;
}

/** 轻量提示：优先复用覆盖层 showToast，不可用时降级 console.log */
function notify(msg) {
  try {
    require('./ui').showToast(msg, 2000);
    return;
  } catch (_) {}
  try { console.log('[about]', msg); } catch (_) {}
}

