/** 构建卡片 HTML */
function buildInner(version) {
  const metaRows = [
    ['技术栈', 'Electron 33'],
    ['版本', 'v' + version],
  ].map(function (r) {
    return '<div class="tokfree-about-meta-row"><span class="tokfree-about-meta-key">' + r[0] + '</span><span class="tokfree-about-meta-val">' + r[1] + '</span></div>';
  }).join('');

  const links = LINKS.map(function (l) {
    return '<button class="tokfree-about-link" data-link="' + l.id + '"><span class="tokfree-about-link-icon">' + l.icon + '</span>' + l.label + '</button>';
  }).join('');

  return '<button id="tokfree-about-close" title="关闭">×</button>' +
    '<div id="tokfree-about-icon" class="tokfree-about-icon-svg">' + TF_ICON_ABOUT + '</div>' +
    '<div id="tokfree-about-name">TokFree</div>' +
    '<div id="tokfree-about-version">v' + version + '</div>' +
    '<div id="tokfree-about-tagline">零 Token 成本的 AI Agent 桌面端</div>' +
    '<div id="tokfree-about-meta">' + metaRows + '</div>' +
    '<div id="tokfree-about-links">' + links + '</div>' +
    '<div id="tokfree-about-footer">© TokFree</div>';
}

/** HTML 转义 */
function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** 行内格式：**加粗**、反引号代码（输入需已转义） */
function inlineFmt(s) {
  let out = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/`([^`]+)`/g, '<code class="tokfree-md-code">$1</code>');
  return out;
}

/**
 * 轻量 Markdown 渲染：支持 #/##/### 标题、- 与 1. 列表、**加粗**、反引号代码、段落。
 * 不引入任何外部依赖。
 */
function renderMarkdown(md) {
  const lines = String(md == null ? '' : md).replace(/\r\n/g, NL).split(NL);
  const out = [];
  let inList = false;
  let para = [];

  function flushPara() {
    if (para.length) {
      out.push('<p class="tokfree-md-p">' + inlineFmt(escapeHtml(para.join(' '))) + '</p>');
      para = [];
    }
  }
  function closeList() {
    if (inList) { out.push('</ul>'); inList = false; }
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/\s+$/, '');
    if (!line.trim()) { flushPara(); closeList(); continue; }

    const h = /^(#{1,6})\s+(.*)$/.exec(line);
    if (h) {
      flushPara(); closeList();
      const lvl = h[1].length;
      out.push('<h' + lvl + ' class="tokfree-md-h tokfree-md-h' + lvl + '">' + inlineFmt(escapeHtml(h[2])) + '</h' + lvl + '>');
      continue;
    }

    const li = /^[-*]\s+(.*)$/.exec(line);
    if (li) {
      flushPara();
      if (!inList) { out.push('<ul class="tokfree-md-ul">'); inList = true; }
      out.push('<li class="tokfree-md-li">' + inlineFmt(escapeHtml(li[1])) + '</li>');
      continue;
    }

    const oli = /^\d+\.\s+(.*)$/.exec(line);
    if (oli) {
      flushPara();
      if (!inList) { out.push('<ul class="tokfree-md-ul">'); inList = true; }
      out.push('<li class="tokfree-md-li">' + inlineFmt(escapeHtml(oli[1])) + '</li>');
      continue;
    }

    para.push(line.trim());
  }
  flushPara(); closeList();
  return out.join('');
}

/** 返回二维码 data URL（未注入时返回空串） */
function qrDataUrl() {
  if (!QR_BASE64 || QR_BASE64.length < 100) return '';
  return 'data:image/jpeg;base64,' + QR_BASE64;
}

/** 打开「文档」弹窗 */
function openDocModal() {
  if (typeof document === 'undefined') return;
  injectStyle();
  let mask = document.getElementById('tokfree-doc-mask');
  if (!mask) {
    mask = document.createElement('div');
    mask.id = 'tokfree-doc-mask';
    mask.className = 'tokfree-hidden';
    const box = document.createElement('div');
    box.id = 'tokfree-doc-box';
    box.innerHTML = '<button id="tokfree-doc-close" title="关闭">×</button>' +
      '<div id="tokfree-doc-header"><span id="tokfree-doc-title">📖 TokFree 使用说明</span></div>' +
      '<div id="tokfree-doc-body">' + renderMarkdown(DOC_MD) + '</div>';
    mask.appendChild(box);
    document.body.appendChild(mask);
    const closeBtn = box.querySelector('#tokfree-doc-close');
    if (closeBtn) closeBtn.onclick = function () { closeDocModal(); };
    mask.onclick = function (e) { if (e.target === mask) closeDocModal(); };
  }
  mask.classList.remove('tokfree-hidden');
}

/** 关闭「文档」弹窗 */
function closeDocModal() {
  if (typeof document === 'undefined') return;
  const mask = document.getElementById('tokfree-doc-mask');
  if (mask) mask.classList.add('tokfree-hidden');
}

/** 打开「有问题？联系我」二维码弹窗 */
function openQrModal() {
  if (typeof document === 'undefined') return;
  injectStyle();
  let mask = document.getElementById('tokfree-qr-mask');
  if (!mask) {
    mask = document.createElement('div');
    mask.id = 'tokfree-qr-mask';
    mask.className = 'tokfree-hidden';
    const box = document.createElement('div');
    box.id = 'tokfree-qr-box';
    const url = qrDataUrl();
    const body = url
      ? '<img id="tokfree-qr-img" src="' + url + '" alt="联系方式二维码" />'
      : '<div id="tokfree-qr-fallback">二维码暂不可用</div>';
    box.innerHTML = '<button id="tokfree-qr-close" title="关闭">×</button>' +
      '<div id="tokfree-qr-title">有问题？联系我</div>' +
      '<div id="tokfree-qr-sub">扫码添加作者，反馈问题或交流使用</div>' +
      body;
    mask.appendChild(box);
    document.body.appendChild(mask);
    const closeBtn = box.querySelector('#tokfree-qr-close');
    if (closeBtn) closeBtn.onclick = function () { closeQrModal(); };
    mask.onclick = function (e) { if (e.target === mask) closeQrModal(); };
  }
  mask.classList.remove('tokfree-hidden');
}

/** 关闭二维码弹窗 */
function closeQrModal() {
  if (typeof document === 'undefined') return;
  const mask = document.getElementById('tokfree-qr-mask');
  if (mask) mask.classList.add('tokfree-hidden');
}

/** 绑定卡片内的事件 */
function bindEvents(box) {
  const closeBtn = box.querySelector('#tokfree-about-close');
  if (closeBtn) closeBtn.onclick = function () { closeAbout(); };

  const linkBtns = box.querySelectorAll('.tokfree-about-link');
  for (let i = 0; i < linkBtns.length; i++) {
    (function (btn) {
      const id = btn.getAttribute('data-link');
      const cfg = LINKS.filter(function (l) { return l.id === id; })[0];
      btn.onclick = function () {
        if (id === 'docs') { openDocModal(); return; }
        if (id === 'feedback') { openQrModal(); return; }
        notify(cfg ? cfg.tip : ('点击了 ' + id));
      };
    })(linkBtns[i]);
  }
}

/** 确保 DOM 存在（幂等） */
function ensureDom() {
  if (typeof document === 'undefined') return null;
  let mask = document.getElementById('tokfree-about-mask');
  if (mask) return mask;
  injectStyle();
  mask = document.createElement('div');
  mask.id = 'tokfree-about-mask';
  mask.className = 'tokfree-hidden';
  const box = document.createElement('div');
  box.id = 'tokfree-about-box';
  box.innerHTML = buildInner(readVersion());
  mask.appendChild(box);
  document.body.appendChild(mask);
  bindEvents(box);
  return mask;
}

/** 打开「关于」页 */
function openAbout() {
  const mask = ensureDom();
  if (!mask) return;
  mask.classList.remove('tokfree-hidden');
}

/** 关闭「关于」页 */
function closeAbout() {
  if (typeof document === 'undefined') return;
  const mask = document.getElementById('tokfree-about-mask');
  if (mask) mask.classList.add('tokfree-hidden');
}

module.exports = {
  openAbout, closeAbout, injectStyle, readVersion, FALLBACK_VERSION,
  renderMarkdown, openDocModal, closeDocModal, openQrModal, closeQrModal, qrDataUrl,
};
